<template>
  <div class="model-list">
    <header class="header">
      <h1>Web Wide World</h1>
      <p>By Nobdy, For Everyone：平凡人共创普惠世界</p>
    </header>
    <div class="baidu-search-box">
      <input
        v-model="modelUrl"
        type="text"
        class="baidu-input"
        placeholder="请填入场景 URL"
        @keydown.enter="goToViewer"
      />
      <button class="baidu-btn" @click="goToViewer">
        Go
        <svg class="btn-icon" width="18" height="18" viewBox="0 0 20 20">
          <polyline
            points="7 5 13 10 7 15"
            fill="none"
            stroke="#fff"
            stroke-width="2"
            stroke-linecap="round"
            stroke-linejoin="round"
          />
        </svg>
      </button>
    </div>

    <!-- Debug UI 开关 -->
    <div class="debug-switch-row">
      <div class="switch-container">
        <span class="switch-label">Debug 工具面板</span>
        <label class="switch">
          <input v-model="showDebugViewer" type="checkbox" />
          <span class="slider"></span>
        </label>
        <span class="debug-status" :class="{ on: showDebugViewer }">{{ showDebugViewer ? 'ON' : 'OFF' }}</span>
        <span class="debug-hint">进入场景时显示操作面板、FPS、侧边栏等调试工具</span>
      </div>
    </div>

    <!-- 工具入口（meta-editor 已迁出到独立子包 @viewer-plugin/meta-editor，此处入口已移除） -->
    <div v-if="modelList.length > 0" class="models-grid">
      <div v-for="model in modelList" :key="model.id" class="model-card" @click="goToModel(model)">
        <div v-if="(useSceneViewer && model.modelUrlV2 !== '') || (!useSceneViewer && model.modelUrl !== '')">
          <div class="model-preview">
            <div class="model-icon">🎯</div>
            <h3>{{ model.name }}</h3>
          </div>
          <div class="model-info">
            <button class="view-button">查看详情</button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted, watch } from 'vue';
// import { useRouter } from 'vue-router';
// const router = useRouter();
const modelList = ref([]);
const modelUrl = ref('');

const STORAGE_KEY = 'viewer_showDebugViewer';

// 从 localStorage 恢复 Debug 开关状态，默认关闭
function loadShowDebugViewer() {
  try {
    return localStorage.getItem(STORAGE_KEY) === 'true';
  } catch {
    return false;
  }
}

const useSceneViewer = ref(true); // false: 元宇宙查看器, true: 场景查看器
const showDebugViewer = ref(loadShowDebugViewer()); // 是否在查看器中展示 Debug 工具面板

// 开关变化时持久化到 localStorage
watch(showDebugViewer, (val) => {
  try {
    localStorage.setItem(STORAGE_KEY, String(val));
  } catch {
    // 忽略存储异常
  }
});

onMounted(async () => {
  try {
    const isProduction = import.meta.env.MODE === 'production';
    const isQQDomain = window.location.hostname.endsWith('.qq.com') || window.location.hostname === 'qq.com';

    let url;
    if (isProduction) {
      if (isQQDomain) {
        // qq.com 域名 → 无极 API
        url = 'https://api.wuji.qq.com/x/api/wuji_cache/object?appid=my_buddy_test&schemaid=scene_pos_config_v2&schemakey=31bfc3054bb54a299ccf2c06a33162d9';
      } else {
        // 其他域名（如 web-wide-world.space）→ COS 静态 JSON，带时间戳防缓存
        url = `https://mogs-1300354879.cos.ap-shanghai.myqcloud.com/mogs/nobody/gs-viewer/config/scene_v2.json?t=${Date.now()}`;
      }
    } else {
      // dev 模式 → Vite 代理，避免 CORS 跨域问题
      url = '/api_wuji/wuji_cache/object?appid=my_buddy_test&schemaid=scene_pos_config_v2&schemakey=31bfc3054bb54a299ccf2c06a33162d9';
    }

    const requestFile = await fetch(url);

    if (requestFile.status !== 200) {
      throw new Error(`加载失败: ${requestFile.statusText}`);
    }

    const content = await requestFile.json();
    // COS JSON 是直接数组，无极 API 返回 { data: [...] }，兼容两种格式
    modelList.value = Array.isArray(content) ? content : content.data;
    console.log('成功加载场景配置:', content);
  } catch (error) {
    console.error('加载场景配置失败:', error);
  }
  // document.addEventListener('touchmove', touchHandler, { passive: false });
});

const goToModel = (itemInfo) => {
  // 根据开关选择不同的查看器
  const viewerPath = useSceneViewer.value ? '/viewer2' : '/viewer';
  // 根据查看器类型选择不同的URL字段
  const sceneUrl = useSceneViewer.value ? itemInfo.modelUrlV2 : itemInfo.modelUrl;
  const debugParam = showDebugViewer.value ? '&showDebugViewer=true' : '';
  console.log('使用的URL:', sceneUrl, '查看器类型:', useSceneViewer.value ? '场景查看器' : '元宇宙查看器');
  window.location.hash = `#${viewerPath}?sceneUrl=${sceneUrl}${debugParam}`;
};
const goToViewer = () => {
  if (modelUrl.value) {
    // 根据开关选择不同的查看器
    const viewerPath = useSceneViewer.value ? '/viewer2' : '/viewer';
    const debugParam = showDebugViewer.value ? '&showDebugViewer=true' : '';
    window.location.hash = `#${viewerPath}?sceneUrl=${modelUrl.value}${debugParam}`;
  }
};
</script>
